-- 520: Original BrillaPrep NSMQ subj_nsmq_math true_false_problem_of_day beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_520_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_520_guard;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_math_trigonometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A ladder 5 m long leans against a vertical wall and makes an angle of 60° with the horizontal ground. Calculate the exact height up the wall that the ladder reaches.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '5√3/2 m (≈ 4.33 m)' AND q.explanation IS 'The ladder, wall and ground form a right-angled triangle with hypotenuse 5 m. The height h is opposite the 60° angle, so sin 60° = h/5 and h = 5 sin 60° = 5 × √3/2 = 5√3/2 ≈ 4.33 m. The exact surd form uses the standard value sin 60° = √3/2.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_math_calculus' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the coordinates of the turning point of the curve y = x² − 6x + 5 and determine its nature.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS 'Minimum turning point at (3, −4)' AND q.explanation IS 'Differentiate: dy/dx = 2x − 6. At a turning point dy/dx = 0, so 2x − 6 = 0 giving x = 3. Then y = 3² − 6(3) + 5 = 9 − 18 + 5 = −4. The second derivative d²y/dx² = 2 is positive, so the turning point (3, −4) is a minimum.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_tf_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_math_algebra' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The expansion of (a + b)² is a² + b².' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'False' AND q.explanation IS 'Expanding properly: (a + b)² = (a + b)(a + b) = a² + 2ab + b². The cross term 2ab is missing from a² + b², so the statement is false in general; equality holds only when ab = 0.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_tf_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_tf_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_math_trigonometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'For every angle θ, sin²θ + cos²θ = 1.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'This is the fundamental Pythagorean identity. It follows directly from the unit-circle definitions sin θ = y and cos θ = x combined with x² + y² = 1, so it holds for all angles without exception.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_tf_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_tf_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_math_geometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The diagonals of every parallelogram are equal in length.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'False' AND q.explanation IS 'All parallelogram diagonals bisect each other, but they are equal only in special parallelograms such as rectangles and squares. A slanted parallelogram has one long and one short diagonal, so the statement is false in general.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_tf_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_520_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_tf_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_math_statistics' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The range of a data set is the difference between the largest and smallest values.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'By definition, range = maximum value − minimum value. It is the simplest measure of spread, although it depends only on the two extreme values and is therefore sensitive to outliers.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_tf_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_pod_b002_001', 'topic_nsmq_math_trigonometry', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'A ladder 5 m long leans against a vertical wall and makes an angle of 60° with the horizontal ground. Calculate the exact height up the wall that the ladder reaches.', 'problem', 'problem_of_day', NULL, '5√3/2 m (≈ 4.33 m)', 'The ladder, wall and ground form a right-angled triangle with hypotenuse 5 m. The height h is opposite the 60° angle, so sin 60° = h/5 and h = 5 sin 60° = 5 × √3/2 = 5√3/2 ≈ 4.33 m. The exact surd form uses the standard value sin 60° = √3/2.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
